#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Enforces `docs/ORGANIZATION_CONTRACT.md`.
 *
 * Every rule in that document is checked here, and every rule here is in that document. If the two
 * disagree, this file is the one that is wrong — the contract is the statement of intent, and a
 * checker that quietly enforces something else is worse than no checker.
 *
 * Existing violations live in `.organization-baseline.json` as a count per rule. The baseline may
 * only shrink: a count going up fails, and a count that has reached zero fails until its entry is
 * deleted, so nobody inherits an exemption that stopped meaning anything.
 *
 *   node scripts/check-organization.mjs [--json] [--baseline]
 */
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const SRC = path.join(PACKAGE_ROOT, 'src')
const BASELINE = path.join(PACKAGE_ROOT, '.organization-baseline.json')

/* ── the domains, and which may import which (Rule 2) ─────────────────────── */

const TIERS = {
  support: 0,
  formatting: 1,
  data: 1,
  mechanics: 2,
  save: 3,
  knowledge: 3,
  builders: 4,
  charts: 4,
  wiki: 4,
  bot: 4,
  sheets: 4,
  node: 4,
  assets: 4,
  contributions: 4,
  'save-decoder': 4,
}

/* `knowledge/` is prose. It may read catalogs; nothing may compute from it. */
const NOBODY_IMPORTS = new Set(['knowledge'])

/* ── Rule 0: shapes application state actually took here ──────────────────── */

const APP_STATE = [
  ['persisted settings', /\b(?:normalize|default)\w*Settings\b|\b\w+SettingsSchema\b|\blocalStorage\b|\bstorageKey\b/g],
  ['cross-page hub', /\bsharedToolInputs\b|\boverlayShared\w*|\bsyncUptime\w*|\bsyncProgress\w*|\bhubLevels\b/g],
  ['ui options', /\b(?:build|get)\w*(?:SelectItems|DropdownItems|Options)\b|\bmdi-[a-z-]+/g],
  ['ui control state', /\b(?:sortKey|sortDirection|filterKey|activeTab|collapsedSections|columnKey|visibleColumns)\b/g],
  ['import orchestration', /\b\w*ImportPayload\b|\bplanSaveImport\w*|\bexecuteSaveImport\w*|\bskipReason\b/g],
  ['local calculator state', /\b\w*LocalState(?:Schema)?\b|\bcalculatorLocalState\w*/g],
]

/*
 * Rule 4: a consumer's vocabulary, never this package's.
 *
 * `tracker` and `site` only. `page`, `app` and `store` are deliberately absent even though an
 * earlier draft of the contract listed them: a wiki page is a real thing the game has, and
 * `itemsPerPage` is pagination. Banning a word with honest uses teaches everyone to ignore the
 * rule, and then it stops catching the words that have no honest use here.
 */
const CONSUMER_WORDS = /\b(?:tracker|Tracker|TRACKER)\b|\b[A-Za-z_]*(?:SITE|Site)[A-Za-z_]*\b/g

/**
 * The classes that are allowed to exist, each with the reason it is not an entity.
 *
 * Every one of these carries state that genuinely evolves, or is an Error. None of them wraps a
 * row of game data.
 */
const ALLOWED_CLASSES = {
  'mechanics/primitives/unity-random.ts:UnityRandom': 'mirrors Unity\'s PRNG; the seed advances with each draw',
  'node/nrbf/reader.ts:BinaryObject': 'a node in a binary parse tree, built as the stream is read',
  'sheets/client.ts:TowerSheets': 'holds a connection and its auth',
  'mechanics/effective-paths/formula.ts:EffectivePathsFormulaError': 'an Error subclass',
  'mechanics/effective-paths/schema.ts:EffectivePathsSchemaError': 'an Error subclass',
  'mechanics/effective-paths/schema.ts:EffectivePathsInputError': 'an Error subclass',
  'node/nrbf/reader.ts:NRBFReader': 'a cursor over a byte stream; its position advances as it reads',
  'bot/create-bot.ts:TowerBot': 'holds a running command registry',
  'mechanics/calculators/run.ts:CalculatorError': 'an Error subclass',
}

/* ── walking ──────────────────────────────────────────────────────────────── */

function tsFiles(dir, out = []) {
  if (!existsSync(dir)) return out
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry)
    if (statSync(full).isDirectory()) tsFiles(full, out)
    else if (entry.endsWith('.ts')) out.push(full)
  }
  return out
}

function foldersHoldingCode(dir, out = []) {
  if (!existsSync(dir)) return out
  const entries = readdirSync(dir)
  if (entries.some(e => e.endsWith('.ts'))) out.push(dir)
  for (const entry of entries) {
    const full = path.join(dir, entry)
    if (statSync(full).isDirectory()) foldersHoldingCode(full, out)
  }
  return out
}

const rel = file => path.relative(SRC, file).split(path.sep).join('/')
const isGenerated = r => /(^|\/)generated\//.test(r) || /\.generated\.ts$/.test(r)
const isTranscription = r => /\.data\.ts$/.test(r)

/* ── the rules ────────────────────────────────────────────────────────────── */

/**
 * Rules 0, 4, 5, 6 and 8 — everything decided by reading one file.
 *
 * Split out of `check()` because that function crossed the complexity limit, which is the same
 * signal Rule 6 applies to length: a unit doing this many separate things is a folder that never
 * happened. One rule per block, in the order the contract states them.
 */
function checkFile(r, text, add) {
  const generated = isGenerated(r)

  /* Rule 4 — a file never repeats its folder */
  const parts = r.split('/')
  if (parts.length >= 2) {
    const folder = parts[parts.length - 2]
    const base = parts[parts.length - 1].replace(/\.ts$/, '')
    const singular = folder.replace(/s$/, '')
    if (base === folder || base.startsWith(`${folder}-`) || (singular !== folder && base.startsWith(`${singular}-`))) {
      add('name-repeats-folder', r, `'${base}' inside '${folder}/'`)
    }
    if (!/^[a-z0-9]+(?:[.-][a-z0-9]+)*$/.test(base)) add('not-kebab-case', r, base)
  }

  /* Rule 6 — length */
  const lineCount = text.split('\n').length
  if (!generated && !isTranscription(r) && lineCount > 500) {
    add('file-too-long', r, `${lineCount} lines; the cap is 500`)
  }

  if (generated) return

  /* Rule 5 — both headers */
  /*
   * Searched over the first hundred lines rather than the first 1,500 characters. A module with a
   * long prose docblock pushes the generated header past that cap, and `wiki/sources.ts` — which
   * explains at length why there are two community wikis — was reported as missing a header it
   * has. A checker that fails on the files with the most explanation is worse than useless.
   */
  const head = text.split('\n').slice(0, 100).join('\n')
  if (!head.includes('── file map ─')) add('missing-file-map', r, 'no generated file-map header')
  const withoutFileMap = text.replace(/\/\*\s*──[\s\S]*?──\s*\*\//, '')
  if (!/^\s*\/\*\*[\s\S]{60,}?\*\//m.test(withoutFileMap.slice(0, 2000))) {
    add('missing-docblock', r, 'no prose docblock saying what this is for')
  }

  /*
   * Rule 8a — exported types live in types.ts.
   *
   * A type declared beside the one function that returns it is invisible to the module next
   * door, so that module declares its own, and one idea ends up with three names. Types used
   * only inside a file, and not exported, are not the problem and are not checked.
   */
  const base = path.basename(r)
  if (base !== 'types.ts' && base !== 'index.ts') {
    const declared = [...text.matchAll(/^export\s+(?:declare\s+)?(type|interface|enum)\s+(\w+)/gm)]
    if (declared.length > 0) {
      add('types-outside-types-module', r, `${declared.length} exported ${declared.length === 1 ? 'type' : 'types'} (${declared.slice(0, 3).map(m => m[2]).join(', ')}${declared.length > 3 ? ', …' : ''})`)
    }
  }

  /*
   * Rule 8c — no ENTITY classes.
   *
   * Not "no classes". A stateful machine is a legitimate thing to model with one, and the four
   * kinds below are each doing that. What is forbidden is wrapping a row of game data in an
   * object so it can have methods — that has no identity to carry, and it costs every consumer
   * their tree-shaking to import one formula.
   *
   * An allowlist rather than a pattern, because the distinction is a judgement and there are
   * seven of them: adding the eighth should require making that judgement out loud.
   */
  for (const m of text.matchAll(/^export\s+(?:abstract\s+)?class\s+(\w+)/gm)) {
    const why = ALLOWED_CLASSES[`${r}:${m[1]}`]
    if (!why) add('entity-class', r, `class ${m[1]} — model game data as tables and functions, not objects`)
  }
  if (/^(?:usecases?|workflows?|orchestrat\w+)\.ts$/.test(base)) {
    add('orchestration-module', r, 'multi-step flows belong to the platform layer')
  }

  /* Rule 0 — application state */
  for (const [label, pattern] of APP_STATE) {
    const hits = text.match(pattern)
    if (hits) add('app-state', r, `${label} (${hits.length}x, e.g. ${hits[0]})`)
  }

  /* Rule 4 — a consumer's word */
  const consumer = text.match(CONSUMER_WORDS)
  if (consumer) add('consumer-vocabulary', r, `'tracker' appears ${consumer.length}x`)
}

function check() {
  const findings = []
  const add = (rule, where, detail) => findings.push({ rule, where, detail })

  const files = tsFiles(SRC)
  const folders = foldersHoldingCode(SRC)

  /* Rule 1 — there is no internal/ */
  for (const file of files) {
    const r = rel(file)
    if (r.startsWith('internal/')) add('no-internal', r, 'internal/ is abolished; this belongs to a domain or to the platform layer')
  }
  const support = files.filter(f => rel(f).startsWith('support/'))
  if (support.length > 10) add('support-cap', 'support/', `${support.length} files; the cap is 10`)

  /* Rule 2 — domains and direction */
  const byPath = new Map(files.map(f => [rel(f), f]))
  for (const file of files) {
    const r = rel(file)
    const domain = r.includes('/') ? r.split('/')[0] : null
    if (!domain) {
      if (r !== 'index.ts') add('undeclared-domain', r, 'a file at the root of src/ that is not index.ts')
      continue
    }
    if (!(domain in TIERS)) {
      /*
       * `internal/` is already counted by its own rule. Reporting it twice inflates the debt
       * register and, worse, means deleting the folder would drop two numbers at once — which
       * reads as more progress than was made.
       */
      if (domain !== 'internal') add('undeclared-domain', r, `'${domain}' is not a domain in the contract`)
      continue
    }
    if (isGenerated(r)) continue

    const text = readFileSync(file, 'utf8')
    for (const m of text.matchAll(/from\s*'(\.[^']+)'/g)) {
      const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(r), m[1]))
      const target = [`${resolved}.ts`, `${resolved}/index.ts`].find(c => byPath.has(c))
      if (!target) continue
      const targetDomain = target.split('/')[0]
      if (targetDomain === domain || !(targetDomain in TIERS)) continue
      if (NOBODY_IMPORTS.has(targetDomain)) {
        add('imports-knowledge', r, `imports ${target}; nothing may import ${targetDomain}/`)
        continue
      }
      if (TIERS[targetDomain] > TIERS[domain]) {
        add('upward-import', r, `${domain}/ (tier ${TIERS[domain]}) imports ${targetDomain}/ (tier ${TIERS[targetDomain]})`)
      }
    }
  }

  /* Rule 3 — every folder has the same shape */
  for (const dir of folders) {
    const r = path.relative(SRC, dir).split(path.sep).join('/') || '(src)'
    const entries = readdirSync(dir)
    if (!entries.includes('index.ts')) add('missing-index', r, 'no index.ts')
    if (!entries.includes('MAP.md')) add('missing-map', r, 'no MAP.md')

    const depth = r === '(src)' ? 0 : r.split('/').length
    const modules = entries.filter(e => e.endsWith('.ts') && e !== 'index.ts')

    /*
     * Loose files at a domain root: everything belongs to a subdomain, unless the domain has
     * declared itself flat and said why. The declaration lives in its index.ts so the reason is
     * where a reader lands, not in a config file nobody opens.
     */
    if (depth === 1 && modules.length > 0) {
      const indexPath = path.join(dir, 'index.ts')
      const declaredFlat = existsSync(indexPath)
        && /This domain is flat:\s*\S/.test(readFileSync(indexPath, 'utf8'))
      if (!declaredFlat) {
        for (const m of modules) add('loose-at-domain-root', `${r}/${m}`, 'belongs in a subdomain, or the domain must declare itself flat')
      }
    }
    /* Subdomain size band. */
    if (depth >= 2 && modules.length > 0 && !r.includes('generated')) {
      if (modules.length > 12) add('subdomain-too-large', r, `${modules.length} modules; the band is 2-12`)
    }
  }

  /* Rules 4, 5, 6, 0 — per file */
  for (const file of files) {
    checkFile(rel(file), readFileSync(file, 'utf8'), add)
  }

  /*
   * An exemption pointing at a file that no longer exists is dead, and dead exemptions are how a
   * list stops meaning anything. The paths in ALLOWED_CLASSES go stale whenever a module moves —
   * unity-random did exactly that on its way into primitives/ — and while a stale key fails safe
   * (the class is reported), leaving it there invites someone to re-add the path without making
   * the judgement again.
   */
  for (const key of Object.keys(ALLOWED_CLASSES)) {
    const [file] = key.split(':')
    if (!existsSync(path.join(SRC, file))) {
      add('stale-class-allowance', key, 'allowlisted class in a file that no longer exists')
    }
  }

  /* Rule 7 — the public surface */
  const pkg = JSON.parse(readFileSync(path.join(PACKAGE_ROOT, 'package.json'), 'utf8'))
  for (const key of Object.keys(pkg.exports ?? {})) {
    if (key === '.' || key === './package.json') continue
    if (key.includes('*')) {
      add('wildcard-export', key, 'a wildcard publishes the source tree; name the domain instead')
      continue
    }
    const domain = key.replace(/^\.\//, '').split('/')[0]
    if (!(domain in TIERS) && !key.endsWith('.json')) {
      add('export-not-a-domain', key, `'${domain}' is not a domain in the contract`)
    }
  }

  return findings
}

/* ── baseline ─────────────────────────────────────────────────────────────── */

function counts(findings) {
  const out = {}
  for (const f of findings) out[f.rule] = (out[f.rule] ?? 0) + 1
  return out
}

function main() {
  const findings = check()
  const now = counts(findings)

  if (process.argv.includes('--json')) {
    console.log(JSON.stringify({ counts: now, findings }, null, 2))
    return
  }

  if (process.argv.includes('--baseline')) {
    writeFileSync(BASELINE, `${JSON.stringify(now, null, 2)}\n`)
    console.log(`Wrote baseline: ${Object.values(now).reduce((a, b) => a + b, 0)} violations across ${Object.keys(now).length} rules.`)
    return
  }

  const before = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, 'utf8')) : {}
  const rules = [...new Set([...Object.keys(before), ...Object.keys(now)])].sort()

  const worse = []
  const stale = []
  console.log('RULE'.padEnd(26), 'NOW'.padStart(6), 'ALLOWED'.padStart(8))
  for (const rule of rules) {
    const n = now[rule] ?? 0
    const allowed = before[rule] ?? 0
    const mark = n > allowed ? '  <-- WORSE' : n < allowed ? '  (improved)' : ''
    console.log(rule.padEnd(26), String(n).padStart(6), String(allowed).padStart(8), mark)
    if (n > allowed) worse.push({ rule, n, allowed })
    if (allowed > 0 && n === 0) stale.push(rule)
  }

  const total = Object.values(now).reduce((a, b) => a + b, 0)
  console.log(`\n${total} violations of docs/ORGANIZATION_CONTRACT.md`)

  if (worse.length > 0) {
    console.log('\nThese got worse:')
    for (const { rule, n, allowed } of worse) {
      console.log(`\n  ${rule}: ${n} (allowed ${allowed})`)
      for (const f of findings.filter(f => f.rule === rule).slice(0, 8)) {
        console.log(`      ${f.where} — ${f.detail}`)
      }
    }
    console.log('\nThe baseline is a debt register, not permission. Fix it, do not raise it.')
    process.exitCode = 1
  }

  if (stale.length > 0) {
    console.log(`\nThese rules are now clean; delete their baseline entries: ${stale.join(', ')}`)
    process.exitCode = 1
  }
}

main()
